import{_ as t,o as e,c as r,a2 as l}from"./chunks/framework.BZO4qERu.js";const i="/assets/left-left.D4HWdxDR.png",o="/assets/right-right.L4veory2.png",n="/assets/left-right.BgOg754i.png",s="/assets/right-left.CxYU6Kac.png",p="/assets/red-black-tree.BQ3i_0sc.png",u=JSON.parse('{"title":"二叉查找树","description":"","frontmatter":{},"headers":[],"relativePath":"algorithm/binary-search-tree.md","filePath":"algorithm/binary-search-tree.md","lastUpdated":1781086744000}'),h={name:"algorithm/binary-search-tree.md"};function c(d,a,g,m,_,f){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="二叉查找树" tabindex="-1">二叉查找树 <a class="header-anchor" href="#二叉查找树" aria-label="Permalink to &quot;二叉查找树&quot;">​</a></h1><p>二叉查找树是一种特殊的二叉树，有以下几个特征：</p><ol><li>左子树上的所有结点的值都小于或等于它的根结点的值。</li><li>右子树上的所有节点的值都大于或等于它的根结点的值。</li><li>左右子树分别也都是二叉查找树。</li></ol><p>顾名思义，二叉查找树是用来“查找”的，那么他是如何查找的呢？其实就是从根节点开始，根据二叉查找树的（1）和（2）性质，决定进入左子树或者右子树，然后一直往下查找，直到找到待找的元素。</p><p>这种查找的模式与二分法有着相似之处，插入和查找的时间复杂度均为 O(logn).</p><p>但是普通的二叉查找树会有特殊情况，当顺序插入结点时，二叉查找树可能会退化成具有 n 个结点的线性链表，这时最坏情况，插入和查找的时间复杂度都是 O(n).</p><h2 id="平衡二叉查找树" tabindex="-1">平衡二叉查找树 <a class="header-anchor" href="#平衡二叉查找树" aria-label="Permalink to &quot;平衡二叉查找树&quot;">​</a></h2><p>为了解决这种可能会退化的情况，出现了一种能够在任何顺序插入元素时，都能保持树的高度较小的二叉查找树，我们称之为 <strong>平衡二叉查找树（Self-balancing Binary Search Tree）</strong>。</p><p>实现了 平衡二叉查找树 的数据结构有很多种，例如：</p><ul><li>2-3 树</li><li>AVL 树</li><li>红黑树</li></ul><p>下面我们介绍一下 AVL树 和 红黑树。</p><h2 id="avl树" tabindex="-1">AVL树 <a class="header-anchor" href="#avl树" aria-label="Permalink to &quot;AVL树&quot;">​</a></h2><p>AVL树 这个名字取自它的两位发明者（<strong>A</strong>delson-<strong>V</strong>elsky and <strong>L</strong>andis），它是首个被发明的 自平衡二叉查找树，是在 1962 年的论文 “An Algorithm for the organization of information&quot; 中被提出的。</p><p>我们先来看看 AVL树 的定义。</p><p>首先我们定义 节点X 的<strong>平衡因子（balence factor）</strong> ：<code>BF(X) = Height(X的右子树) - Height(X的左子树)</code></p><p>如果二叉查找树中的所有结点 X 都满足 <code>BF(X) = {-1, 0, 1}</code>，那么这个二叉查找树被称为 AVL树。</p><p>用通俗的话讲 AVL树：它是一棵空树或者它的左右两个子树的高度差的绝对值不超过 1，并且左右两子树都满足 AVL树的性值。</p><p>AVL树 中定义了旋转操作，当某个结点的平衡因子大于等于2时，AVL树会旋转来调整树的结构，来重新满足 平衡因子小于2 的要求。</p><p>AVL树只有在插入或者删除结点时，可能会造成失去平衡，需要旋转的情况，而且 只有在那些 插入/删除 结点到根结点的路径上的结点有可能出现失衡，因为只有那些结点的子树结构发生了变化。</p><p>当插入新结点导致不平衡时, 我们需要找到距离新节点最近的不平衡结点为轴来转动AVL树来达到平衡。下面分四种情况介绍。</p><h3 id="左子树的左子树插入结点-左左" tabindex="-1">左子树的左子树插入结点（左左） <a class="header-anchor" href="#左子树的左子树插入结点-左左" aria-label="Permalink to &quot;左子树的左子树插入结点（左左）&quot;">​</a></h3><p><img src="'+i+'" alt="left-left"></p><h3 id="右子树的右子树插入结点-右右" tabindex="-1">右子树的右子树插入结点（右右） <a class="header-anchor" href="#右子树的右子树插入结点-右右" aria-label="Permalink to &quot;右子树的右子树插入结点（右右）&quot;">​</a></h3><p><img src="'+o+'" alt="right-right"></p><h3 id="左子树的右子树插入结点-左右" tabindex="-1">左子树的右子树插入结点（左右） <a class="header-anchor" href="#左子树的右子树插入结点-左右" aria-label="Permalink to &quot;左子树的右子树插入结点（左右）&quot;">​</a></h3><p><img src="'+n+'" alt="left-right"></p><h3 id="右子树的左子树插入结点-右左" tabindex="-1">右子树的左子树插入结点（右左） <a class="header-anchor" href="#右子树的左子树插入结点-右左" aria-label="Permalink to &quot;右子树的左子树插入结点（右左）&quot;">​</a></h3><p><img src="'+s+'" alt="right-left"></p><h2 id="红黑树" tabindex="-1">红黑树 <a class="header-anchor" href="#红黑树" aria-label="Permalink to &quot;红黑树&quot;">​</a></h2><p>红黑树在二叉查找树的基础上增加了着色和相关的性质，使得红黑树在无论怎么插入元素时，可以达到<strong>相对平衡</strong>的状态，从而保证了红黑树的查找、插入、删除的时间复杂度最坏为 O(logn)，加快检索效率。</p><p>红黑树必须满足 5 条性质</p><ol><li>每个结点都是红色或者黑色的。</li><li>根结点必须是黑色的。</li><li>每个叶子结点（NIL 或者 空结点）都是黑色的，即叶子结点不存储数据。</li><li>每个红色结点的两个子结点都是黑色的。</li><li>从任一结点到其每个叶子的所有路径都包含相同数目的黑色结点。</li></ol><p>下图是一个典型的红黑树</p><p><img src="'+p+'" alt="red-black-tree"></p><p>对于红黑树来说，插入和删除操作可能会导致红黑树的某些性质被违背，因此可能需要 <strong>变色</strong> 和 <strong>旋转</strong> 操作来恢复相关性质。</p><p>恢复红黑树的性质需要 O(logn) 的变色操作 和 不超过三次（插入操作不超过两次）的旋转操作。所以总体来说，插入和删除操作虽然复杂，但是最坏的时间复杂度仍然保持在了 O(logn)。</p><h3 id="avl树-与-红黑树" tabindex="-1">AVL树 与 红黑树 <a class="header-anchor" href="#avl树-与-红黑树" aria-label="Permalink to &quot;AVL树 与 红黑树&quot;">​</a></h3><p>红黑树是“近似平衡”的。红黑树相比avl树，在检索的时候效率其实差不多，都是通过平衡来二分查找。但对于插入删除等操作效率提高很多。红黑树不像avl树一样追求绝对的平衡，他允许局部很少的不完全平衡，这样对于效率影响不大，但省去了很多没有必要的调平衡操作，avl树调平衡有时候代价较大，所以效率不如红黑树。</p><p>AVL树是一种高度平衡的二叉树，所以查找的非常高，但是，有利就有弊，AVL树为了维持这种高度的平衡，就要付出更多代价。每次插入、删除都要做调整，就比较复杂、耗时。所以，对于有频繁的插入、删除操作的数据集合，使用AVL树的代价就有点高了。</p><p>红黑树只是做到了近似平衡，并不严格的平衡，所以在维护的成本上，要比AVL树要低。 所以，红黑树的插入、删除、查找各种操作性能都比较稳定。对于工程应用来说，要面对各种异常情况，为了支撑这种工业级的应用，我们更倾向于这种性能稳定的平衡二叉查找树。</p>',40)])])}const A=t(h,[["render",c]]);export{u as __pageData,A as default};
